"""Explain large free, metadata address wrappers and mapping responsibilities."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1805': ('큰 상자를 반납할 때는 상자 중간이 아니라 시작 위치를 알려 줘야 해요. 잘못된 위치라는 경고와 작업 중단은 서로 다른 동작이에요.', '큰 할당 해제의 시작 주소·크기·경고 뒤 흐름을 이해합니다.', 'head page 시작 주소와 ptr를 나란히 적고, 길이에는 page_size(page)의 결과를 넣으세요.', ['kmsan_kfree_large는 큰 메모리 할당을 해제할 때 검사 정보를 바꾸는 hook이에요. 인자는 ptr 하나예요. 앞의 할당 hook처럼 요청 size를 인자로 받지 않아요.', '검사가 꺼졌거나 도구 자신의 처리 중이면 돌아가요. 정상 경로에서는 runtime에 들어가 virt_to_head_page로 이 주소가 속한 묶음의 대표 페이지를 얻어요. head page는 여러 페이지로 된 묶음을 대표하는 첫 페이지예요.', '그다음 ptr와 page_address(page)를 비교해요. page_address는 대표 페이지의 시작 주소예요. 서로 다르면 KMSAN_WARN_ON으로 경고해요. 정상 호출자는 올바른 시작 주소를 전달해야 해요.', '경고 뒤 실행이 계속되는 경우 바로 poison 호출로 이어져요. 이 줄 다음에 별도의 return이 없어요. 시작 주소를 올바르게 고쳐 주는 대입도 없고 원래 ptr를 그대로 넘겨요. 따라서 잘못된 주소를 넣어도 안전하게 거절한다고 생각하면 안 돼요.', '검사 길이는 page_size(page)에서 얻어요. 예시로 이 결과가 8192이면 8192바이트 범위에 표시를 요청해요. 이전 요청 길이가 얼마였는지 이 함수가 별도 기록에서 읽어 오는 코드는 없어요.', '옵션은 CHECK와 FREE를 함께 전달해 검사 범위 진단과 해제 관련 원인 표시를 요청해요. 마지막에는 runtime에서 나와요. 이 수업은 경고 뒤 흐름을 읽는 활동이며 실제 잘못된 주소로 해제하거나 shadow를 쓰는 실험은 하지 않아요.'], [('큰 할당 해제 hook의 검사 길이는 어디서 얻나요?', ['예전 요청 size를 별도 기록에서 항상 읽어요', '대표 페이지의 page_size(page)에서 얻어요'], '정답은 두 번째예요. 함수는 요청 size를 받지 않고 페이지를 찾은 뒤 크기를 얻어요. 할당 hook의 size와 해제 hook의 page_size를 구별하세요.'), ('경고 뒤 실행이 계속된다면 시작 주소 불일치 경고 바로 다음에 return하나요?', ['아니요. 원래 ptr를 쓰는 poison 호출로 이어져요', '네. 경고 자체가 항상 return 명령이에요'], '정답은 첫 번째예요. 본문에 그 위치의 return이 없어요. 경고 설정에 따라 실행이 멈출 수는 있지만, 계속되는 경우 잘못된 ptr를 자동 수정하지도 않아요.')]), 'os1806': ('같은 물건 번호로 준비표와 원인표를 각각 찾을 수 있어요. 어느 표를 찾는지 선택값만 달리 보내는 두 도우미예요.', '주소 조회의 종류 선택과 실제 주소 계산의 책임을 구별합니다.', '같은 addr에서 SHADOW 조회와 ORIGIN 조회로 갈라지는 두 화살표를 그리세요.', ['vmalloc_shadow와 vmalloc_origin은 데이터 주소에 맞는 검사 정보 주소를 구하는 짧은 도우미예요. shadow는 준비 상태표, origin은 원인 정보표예요. 실제 데이터 내용을 반환하는 함수가 아니에요.', '두 함수 모두 입력 addr를 void 포인터로 바꾸어 kmsan_get_metadata에 전달해요. 달라지는 두 번째 인자는 KMSAN_META_SHADOW와 KMSAN_META_ORIGIN이에요. 같은 데이터 주소에서 어떤 검사표를 찾을지 선택해요.', '조회 결과는 unsigned long으로 바꾸어 반환해요. 여기서는 주소를 숫자 형태로 다루기 위한 형식이에요. 주소를 숫자로 표현했다고 그 주소의 데이터 바이트를 읽거나 복사한 것은 아니에요.', '실제 주소 분류와 계산은 아래의 kmsan_get_metadata가 맡아요. 특히 origin 조회는 주소를 4바이트 경계로 내려 맞추는 처리도 있어요. 그러므로 두 도우미가 언제나 입력에 단순히 같은 차이만 더한다고 외우면 안 돼요.', '설명용 모델에서는 정렬된 주소 1012에 shadow 차이 1000, origin 차이 2000을 더해 2012와 3012로 대응시킬 수 있어요. 이런 숫자는 입력과 결과를 따라가기 위한 예예요. 실제 기종의 주소 배치를 정한 상수가 아니에요.', '검사 정보는 실제 데이터와 다른 공간이에요. 가상 주소에서 일정한 관계가 있어도 물리 페이지까지 같다는 뜻은 아니에요. 반환 결과의 의미는 조회 함수의 조건까지 연결해서 읽어야 해요.'], [('두 도우미가 같은 addr와 함께 다르게 전달하는 것은 무엇인가요?', ['데이터 주소를 무조건 0으로 바꾼 값이에요', 'shadow 또는 origin이라는 조회 종류예요'], '정답은 두 번째예요. 두 함수의 차이는 KMSAN_META_SHADOW와 KMSAN_META_ORIGIN이에요. 주소의 실제 변환은 공통 조회 함수가 처리해요.'), ('모델에서 정한 주소 차이 1000과 2000을 모든 기종의 실제 주소 규칙으로 써도 되나요?', ['아니요. 입력과 결과를 설명하기 위한 모델 숫자예요', '네. 모든 커널에서 같은 고정 주소 규칙이에요'], '정답은 첫 번째예요. 실제 주소는 기종과 영역, 정렬 등의 조건을 따라요. 모델 숫자와 실제 주소 계약을 나누어 기억하세요.')]), 'os1807': ('도로 표지판을 지우는 일과 남아 있는 길 안내 기억을 정리하는 일은 따로 있어요. 어느 담당자가 어느 범위를 처리하는지 따라가 봐요.', '검사 정보 연결 해제와 상위 함수의 데이터·캐시·TLB 처리를 구별합니다.', 'shadow 연결 해제 → origin 연결 해제 → shadow 캐시 처리 → origin 캐시 처리 순서를 적으세요.', ['vunmap은 가상 주소와 페이지의 연결을 해제하는 일을 뜻해요. 연결 해제와 실제 페이지 메모리 반납은 별개 작업이에요. 이 함수의 본문에 페이지를 직접 free하는 호출이 있는지도 따로 봐야 해요.', 'kmsan_vunmap_range_noflush는 데이터의 start와 end를 받아 대응하는 shadow 범위와 origin 범위를 구해요. 범위는 시작을 포함하고 끝은 포함하지 않아요. 예를 들어 100부터 104 직전까지면 100, 101, 102, 103의 네 위치예요.', '먼저 shadow 범위를 __vunmap_range_noflush에 넘기고 그다음 origin 범위를 넘겨요. 이 hook의 두 호출 대상은 검사표 공간이에요. 데이터 범위를 직접 연결 해제하는 호출이라고 혼동하지 마세요.', '이어 두 범위 각각에 flush_cache_vmap을 호출해요. 캐시는 빠른 접근을 위해 정보를 보관하는 장치예요. 이름에 noflush가 있어도 본문에는 실제로 두 캐시 처리 호출이 있어요. 함수 이름만으로 세부 동작을 단정하지 마세요.', '이 짧은 본문에는 enabled나 in_runtime 조기 반환 조건도 없어요. mm/vmalloc.c의 상위 wrapper는 이 hook를 부른 뒤 데이터 범위의 연결을 해제해요. 그보다 바깥 vunmap_range는 앞에서 캐시 처리, 뒤에서 주소 변환 기억인 TLB 처리를 요청해요.', '따라서 검사표, 데이터, 캐시, TLB의 책임을 호출 단계별로 나눠 읽어야 해요. 이 hook 안에 직접 TLB 호출이 없다는 사실만으로 전체 해제 과정에 TLB 처리가 없다고 결론 내릴 수 없어요.'], [('이 KMSAN hook가 내부 unmap에 넘기는 범위는 무엇인가요?', ['실제 데이터 한 범위뿐이에요', 'shadow와 origin의 두 범위예요'], '정답은 두 번째예요. 데이터 연결 해제는 이 hook를 부르는 상위 wrapper에 따로 있어요. 호출 계층에 따라 대상 공간을 구별하세요.'), ('이름에 noflush가 있으니 본문에 캐시 처리도 없다고 판단해도 되나요?', ['아니요. flush_cache_vmap을 두 번 호출해요', '네. 이름만 보면 모든 구현을 알 수 있어요'], '정답은 첫 번째예요. 실제 네 호출을 읽으면 두 unmap 뒤 두 cache 호출이 있어요. 이름보다 본문의 구체적인 동작을 확인하세요.')]), 'os1808': ('새 주소로 사용할 공간에 검사표를 새로 붙이는 작업이에요. 예전에 쓰던 검사표를 복사해 오는 것인지 새로 준비하는 것인지 구별해 봐요.', 'ioremap용 새 검사 페이지와 실제 사용하는 인자를 이해합니다.', '입력 목록의 phys_addr·page_shift와 본문의 새 할당·PAGE_SHIFT를 따로 표시하세요.', ['ioremap은 장치 등의 물리 주소 범위를 커널 가상 주소로 접근하도록 연결하는 과정과 관련돼요. kmsan_ioremap_page_range는 그 과정에 필요한 검사 정보를 준비해요. 실제 장치 데이터를 복사하는 함수는 아니에요.', '원문 주석은 새 shadow·origin 페이지를 만들고, 해당 물리 페이지에 이미 있던 검사 정보가 있어도 사용하지 않는다고 설명해요. 기존 원인 기록을 memcpy로 그대로 옮기는 동작으로 해석하면 안 돼요.', '검사가 꺼졌거나 도구 자신의 처리 중이면 0을 반환해요. 정상 경로는 nr = (end - start) / PAGE_SIZE로 반복 수를 계산해요. 유효하고 페이지 경계에 맞는 8192바이트 범위와 페이지 크기 4096의 예라면 두 번이에요.', '각 반복에서는 ZERO 표시를 포함한 조건으로 shadow와 origin을 새로 할당해요. 실제 호출은 alloc_pages(gfp_mask, 1)이에요. 여기서 1은 order라서 할당 묶음은 두 페이지라는 점도 구별해야 해요. 연결 요청의 범위 길이는 반복마다 PAGE_SIZE예요.', '함수 인자로 phys_addr와 page_shift를 받지만 이 본문은 그 두 인자를 사용하지 않아요. 검사 페이지 연결 함수에는 받은 page_shift 대신 상수 PAGE_SHIFT를 전달해요. 반면 보호 설정 prot는 전달받은 값을 사용해요.', '따라서 인자가 있다는 사실만으로 그 값을 모든 내부 호출에 그대로 넘긴다고 추측할 수 없어요. 새 페이지 확보, 가상 주소 연결, 기존 데이터 복사는 서로 다른 작업이에요. 실패와 반납의 정확한 흐름도 별도 조건으로 살펴야 하며 여기서 전체 자원 정리가 증명된 것은 아니에요.'], [('이 hook는 phys_addr의 기존 shadow 내용을 복사해 재사용하나요?', ['네. 기존 검사표를 항상 memcpy해요', '아니요. 새 검사 페이지를 할당해요'], '정답은 두 번째예요. 주석은 기존 검사 정보를 무시한다고 설명하고 본문은 alloc_pages를 호출해요. 실제 물리 데이터의 연결과 검사표 준비를 구별하세요.'), ('검사 페이지 연결 함수에 넘기는 shift는 무엇인가요?', ['상수 PAGE_SHIFT예요', '언제나 인자로 받은 page_shift예요'], '정답은 첫 번째예요. 내부 호출의 마지막 인자에 PAGE_SHIFT가 직접 적혀 있어요. 비슷한 이름이어도 매개변수와 상수는 다른 값이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_447.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
